import dayjs from '/dayjs/src'
import utc from '/dayjs/src/plugin/utc'
import timezone from '/dayjs/src/plugin/timezone'
import moment from 'moment-timezone'

dayjs.extend(utc)
dayjs.extend(timezone)

const NY = 'America/New_York'
const LA = 'America/Los_Angeles'
const t = 1401638400000

test('non-string input treated as absolute instant', () => {
  const a = dayjs.tz(t, NY).format()
  const b = dayjs.tz(new Date(t), NY).format()
  const c = dayjs.tz(dayjs(t), NY).format()
  const m = moment.tz(t, NY).format()
  console.log('dayjs.tz(t, NY)          =', a)
  console.log('dayjs.tz(new Date(t),NY) =', b)
  console.log('dayjs.tz(dayjs(t), NY)   =', c)
  console.log('moment.tz(t, NY)         =', m)
  expect(a).toBe('2014-06-01T08:00:00-04:00')
  expect(b).toBe(a)
  expect(c).toBe(a)
  expect(m).toBe(a)
})

test('milliseconds / offset rounding', () => {
  const dMs = dayjs('2014-06-01T12:00:00.500Z').tz(LA)
  const mMs = moment('2014-06-01T12:00:00.500Z').tz(LA)
  console.log('dayjs  format(Z) =', dMs.format('Z'), '| format() =', dMs.format(), '| valueOf =', dMs.valueOf())
  console.log('moment format(Z) =', mMs.format('Z'), '| format() =', mMs.format(), '| valueOf =', mMs.valueOf())
  expect(dMs.format('Z')).toBe('-07:00')
  expect(dMs.valueOf()).toBe(mMs.valueOf())

  const dWhole = dayjs('2014-06-01T12:00:00Z').tz(LA)
  console.log('dayjs whole format(Z) =', dWhole.format('Z'))
  expect(dWhole.format('Z')).toBe('-07:00')
})

